import{_ as i,o as e,c as r,ag as t}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-09-11（AI 前沿）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-09-11.md","filePath":"topics/ai-system-architecture/science-daily-2026-09-11.md"}'),l={name:"topics/ai-system-architecture/science-daily-2026-09-11.md"};function o(n,a,s,c,h,u){return e(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="科学日报-·-2026-09-11-ai-前沿" tabindex="-1">科学日报 · 2026-09-11（AI 前沿） <a class="header-anchor" href="#科学日报-·-2026-09-11-ai-前沿" aria-label="Permalink to &quot;科学日报 · 2026-09-11（AI 前沿）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-11.md</code> — 第22期</p></blockquote><hr><h2 id="gpu-cfr-编译博弈为静态数据流-cfr-提速-80×-arxiv-2609-11923" tabindex="-1">GPU-CFR：编译博弈为静态数据流，CFR 提速 80×（arXiv:2609.11923） <a class="header-anchor" href="#gpu-cfr-编译博弈为静态数据流-cfr-提速-80×-arxiv-2609-11923" aria-label="Permalink to &quot;GPU-CFR：编译博弈为静态数据流，CFR 提速 80×（arXiv:2609.11923）&quot;">​</a></h2><ul><li>CFR 一直 CPU 快于 GPU：逐轮扫数十亿状态博弈树，每次微秒级 gather/scatter，GPU 上内核启动/框架分派占主导。</li><li>洞察：对固定博弈，「除数值外一次 CFR 迭代的一切在首轮前已知」→ 静态数据流 + CUDA Graph 重放，规避全部调度开销，<strong>约 80× 加速</strong>。</li><li>架构启发：「编译期静态化 + 图重放」——把变化隔离在数值、把不变结构固化的思想，对博弈求解、大规模数值负载的 GPU 化有通用价值。</li></ul><h2 id="mindtopo-基础模型能否在拓扑空间推理-arxiv-2609-11900" tabindex="-1">MindTopo：基础模型能否在拓扑空间推理（arXiv:2609.11900） <a class="header-anchor" href="#mindtopo-基础模型能否在拓扑空间推理-arxiv-2609-11900" aria-label="Permalink to &quot;MindTopo：基础模型能否在拓扑空间推理（arXiv:2609.11900）&quot;">​</a></h2><ul><li>空间推理不只有度量（距离/角度/形状），还有<strong>连续形变下不变的拓扑关系</strong>；现有评测几乎只盯着度量/视角相关关系。</li><li>基于认知科学+形式拓扑构建基准 Topo，覆盖连续性、分离性、次序、包围、纽结，各在两个认知层级评测。</li><li>意义：把形式拓扑引入 LLM 推理评测，评估/提升模型的抽象空间推理能力。</li></ul><h2 id="领域化-llm-幻觉检测-多信号融合-arxiv-2609-11878" tabindex="-1">领域化 LLM 幻觉检测：多信号融合（arXiv:2609.11878） <a class="header-anchor" href="#领域化-llm-幻觉检测-多信号融合-arxiv-2609-11878" aria-label="Permalink to &quot;领域化 LLM 幻觉检测：多信号融合（arXiv:2609.11878）&quot;">​</a></h2><ul><li>管线：微调 DeBERTa-v3 分类 + MC Dropout 不确定性 + 温度校准，HaluEval 上 F1=0.915、AUROC=0.977（QA 0.97 / 摘要 0.96 / 对话 0.82）；MC Dropout 推理再提到 93.2%。</li><li>上下文消融证实真在推理而非捷径分类。</li></ul><h2 id="llm-内部知识检索机制-逐层干预-arxiv-2609-11859" tabindex="-1">LLM 内部知识检索机制：逐层干预（arXiv:2609.11859） <a class="header-anchor" href="#llm-内部知识检索机制-逐层干预-arxiv-2609-11859" aria-label="Permalink to &quot;LLM 内部知识检索机制：逐层干预（arXiv:2609.11859）&quot;">​</a></h2><ul><li>从问题末尾隐状态做逐层干预，在 Qwen/Llama/Gemma 上分离「配对条件请求方向」「全局请求方向」「选择候选」，追踪表征逐层传播/分离。</li><li>意义：可解释性 + 知识操纵的观测面。</li></ul><h2 id="相关-见-ai-brain-递归自我改进-the-last-ai-built-by-humans-arxiv-2609-11873" tabindex="-1">相关（见 ai-brain）：递归自我改进 The Last AI Built by Humans（arXiv:2609.11873） <a class="header-anchor" href="#相关-见-ai-brain-递归自我改进-the-last-ai-built-by-humans-arxiv-2609-11873" aria-label="Permalink to &quot;相关（见 ai-brain）：递归自我改进 The Last AI Built by Humans（arXiv:2609.11873）&quot;">​</a></h2>',12)])])}const p=i(l,[["render",o]]);export{m as __pageData,p as default};
